class Solution:
    def createGrid(self, m: int, n: int) -> list[str]:
        grid = [['#'] * n for _ in range(m)]   # block everything: O(m * n)
        for c in range(n):
            grid[0][c] = '.'                    # go right along the top row
        for r in range(m):
            grid[r][n - 1] = '.'                # then down the right column
        return [''.join(row) for row in grid]
